#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[t] = (DATA_TYPE) t;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // --------------------------------------------------------------------
    // Pure functional definitions matching the original C update scheme.
    //
    // We avoid explicit RDom-based updates here and instead express the
    // final values per (i,j) using piecewise expressions (select()).
    //
    // To keep Halide's bounds analysis happy even under aggressive
    // vectorization, we wrap hz, ex1, ey1 with repeat_edge() boundary
    // conditions so that any out-of-bounds neighbor access (which may
    // arise in dead code paths for vectorized lanes) is still defined.
    // Semantically, for the active lanes we never rely on those values,
    // so the results match the original stencil exactly.
    // --------------------------------------------------------------------

    // Dynamic extents in i (rows) and j (cols) as Expr.
    Expr extent_j = ex_param.dim(0).extent();  // ny
    Expr extent_i = ex_param.dim(1).extent();  // nx

    // Clamp hz to its edges for any potential out-of-bounds neighbor access.
    Func hz_clamped("hz_clamped");
    hz_clamped = Halide::BoundaryConditions::repeat_edge(hz_param);

    // 1) ey update:
    //
    // C reference:
    //   for (j = 0; j < ny; j++) ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide (row-major in i, column-major in j but stored as (j,i)):
    //   i == 0: boundary row set to fict_param
    //   i >  0: interior row updated from ey_param and hz_param
    ey1(j, i) = select(
        i == 0,
        fict_param,
        ey_param(j, i) -
            half * (hz_clamped(j, i) - hz_clamped(j, i - 1))
    );

    // 2) ex update:
    //
    // C reference:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide:
    //   j == 0: left column remains unchanged (ex_param)
    //   j >  0: interior columns updated from ex_param and hz_param
    ex1(j, i) = select(
        j == 0,
        ex_param(j, i),
        ex_param(j, i) -
            half * (hz_clamped(j, i) - hz_clamped(j - 1, i))
    );

    // Boundary conditions for the newly-updated ex1 and ey1, used only
    // in the hz stencil. These are never observed at out-of-bounds
    // positions in the original algorithm, but they allow Halide to
    // generate vectorized code without adding explicit bounds checks.
    Func ex1_clamped("ex1_clamped");
    Func ey1_clamped("ey1_clamped");
    ex1_clamped = Halide::BoundaryConditions::repeat_edge(ex1);
    ey1_clamped = Halide::BoundaryConditions::repeat_edge(ey1);

    // 3) hz update:
    //
    // C reference:
    //   for (i = 0; i < nx-1; i++)
    //     for (j = 0; j < ny-1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                           + ey[i+1][j] - ey[i][j]);
    //
    //   The last row/column (i == nx-1 or j == ny-1) keep their old hz.
    //
    // Halide: interior stencil when both neighbors exist, else copy old hz.
    Expr interior_i = i < (extent_i - 1);
    Expr interior_j = j < (extent_j - 1);

    hz1(j, i) = select(
        interior_i && interior_j,
        hz_param(j, i) -
            seven_tenths *
                ((ex1_clamped(j + 1, i) - ex1_clamped(j, i)) +
                 (ey1_clamped(j, i + 1) - ey1_clamped(j, i))),
        hz_param(j, i)
    );

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // --------------------------------------------------------------------
    // Schedule: spatial tiling, parallelization, and vectorization
    // --------------------------------------------------------------------
    //
    // We keep the outer time loop (in C++) strictly sequential because
    // of the true dependencies between time steps, but inside one time
    // step (one realization of this pipeline) all (i,j) points are
    // independent per stage and can be tiled, parallelized, and
    // vectorized safely.
    //
    // Memory layout:
    //   Buffer<num_t,2> is stored row-major with dim 0 (j) contiguous
    //   and dim 1 (i) strided. We therefore vectorize across j and
    //   tile in both i and j for cache locality.
    //
    // We choose moderately sized tiles to:
    //   - keep tiles in L1/L2 cache,
    //   - expose enough parallel work for 32 cores,
    //   - keep j as the innermost, unit-stride dimension.
    // --------------------------------------------------------------------
    const int tile_j = 128;  // tile width  in j (fast dimension)
    const int tile_i = 32;   // tile height in i (slow dimension)

    // Determine a reasonable SIMD width for the host and element type.
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        // Fallback in case natural_vector_size() is not available.
        // 8 floats or 4 doubles map well to AVX2 as a baseline.
        if (type_of<num_t>() == Float(32)) {
            vec_width = 8;
        } else if (type_of<num_t>() == Float(64)) {
            vec_width = 4;
        } else {
            vec_width = 1;
        }
    }

    Var jo("jo"), ji("ji"), io("io"), ii("ii"), tile_index("tile_index");

    // Schedule ey1: compute at root, 2D tiles, parallel over tiles, vectorize in j.
    ey1
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        .vectorize(ji, vec_width);

    // Schedule ex1 similarly.
    ex1
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        .vectorize(ji, vec_width);

    // Schedule hz1 similarly. It depends on ex1/ey1, which are already
    // computed at root, so hz1's schedule does not violate dependencies.
    hz1
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        .vectorize(ji, vec_width);

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i0 = 0; i0 < nx; i0++) {
            for (int j0 = 0; j0 < ny; j0++) {
                std::cerr << ex_final(j0, i0) << '\n';
            }
        }

        // Print ey
        for (int i0 = 0; i0 < nx; i0++) {
            for (int j0 = 0; j0 < ny; j0++) {
                std::cerr << ey_final(j0, i0) << '\n';
            }
        }

        // Print hz
        for (int i0 = 0; i0 < nx; i0++) {
            for (int j0 = 0; j0 < ny; j0++) {
                std::cerr << hz_final(j0, i0) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
