#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    Expr inv_nx = cast<num_t>(Expr(1.0)) / cast<num_t>(Expr(nx));
    Expr inv_ny = cast<num_t>(Expr(1.0)) / cast<num_t>(Expr(ny));

    init_ex(j, i) = cast<num_t>(i * (j + 1)) * inv_nx;
    init_ey(j, i) = cast<num_t>(i * (j + 2)) * inv_ny;
    init_hz(j, i) = cast<num_t>(i * (j + 3)) * inv_nx;

    // Simple but reasonably fast schedule for initialization:
    Target target = get_jit_target_from_environment();
    int vec = natural_vector_size(target, type_of<num_t>());
    if (vec <= 0) vec = 1;

    Var jo("jo"), ji("ji");

    init_fict
        .compute_root()
        .vectorize(t, vec);

    // ex/ey/hz: parallelize across rows (i) and vectorize along contiguous j.
    init_ex
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_ey
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_hz
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // Base (pure) definitions: start with the old values.
    ey1(j, i) = ey_param(j, i);
    ex1(j, i) = ex_param(j, i);
    hz1(j, i) = hz_param(j, i);

    // Update definitions that correspond to the C loops.
    // We keep the algorithm identical to the original code, but will
    // carefully schedule the pure and update stages for locality and
    // parallelism.

    // 1) ey boundary: ey[0][j] = _fict_[t];
    // In Halide: i == 0 row, j runs over all columns.
    RDom r_ey0(0, ey_param.dim(0).extent(), "r_ey0");
    ey1(r_ey0.x, 0) = fict_param;

    // 2) ey interior:
    // for (i = 1; i < nx; i++)
    //   for (j = 0; j < ny; j++)
    //     ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide: i in [1..nx-1], j in [0..ny-1]
    RDom r_ey1(0, ey_param.dim(0).extent(),      // j: 0 .. ny-1
               1, ey_param.dim(1).extent() - 1,  // i: 1 .. nx-1
               "r_ey1");

    ey1(r_ey1.x, r_ey1.y) =
        ey1(r_ey1.x, r_ey1.y) -
        half * (hz_param(r_ey1.x, r_ey1.y) - hz_param(r_ey1.x, r_ey1.y - 1));

    // 3) ex interior:
    // for (i = 0; i < nx; i++)
    //   for (j = 1; j < ny; j++)
    //     ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide: i in [0..nx-1], j in [1..ny-1]
    RDom r_ex(1, ex_param.dim(0).extent() - 1,   // j: 1 .. ny-1
              0, ex_param.dim(1).extent(),       // i: 0 .. nx-1
              "r_ex");

    ex1(r_ex.x, r_ex.y) =
        ex1(r_ex.x, r_ex.y) -
        half * (hz_param(r_ex.x, r_ex.y) - hz_param(r_ex.x - 1, r_ex.y));

    // 4) hz interior:
    // for (i = 0; i < nx - 1; i++)
    //   for (j = 0; j < ny - 1; j++)
    //     hz[i][j] -= 0.7f * (ex[i][j+1] - ex[i][j] +
    //                         ey[i+1][j] - ey[i][j]);
    //
    // Halide: i in [0..nx-2], j in [0..ny-2]
    RDom r_hz(0, hz_param.dim(0).extent() - 1,   // j: 0 .. ny-2
              0, hz_param.dim(1).extent() - 1,   // i: 0 .. nx-2
              "r_hz");

    hz1(r_hz.x, r_hz.y) =
        hz1(r_hz.x, r_hz.y) -
        seven_tenths *
        ((ex1(r_hz.x + 1, r_hz.y) - ex1(r_hz.x, r_hz.y)) +
         (ey1(r_hz.x, r_hz.y + 1) - ey1(r_hz.x, r_hz.y)));

    // --------------------------------------------------------------------
    // Scheduling: optimize data locality, parallelism, and SIMD usage.
    // We preserve the exact mathematical semantics above and only
    // change *how* the computations are ordered and mapped to hardware.
    // --------------------------------------------------------------------
    {
        Target target = get_jit_target_from_environment();
        int vec_width = natural_vector_size(target, type_of<num_t>());
        if (vec_width <= 0) vec_width = 1;

        // Tile sizes chosen for a 32-core x64 machine.
        const int tile_j = 256;  // tile in fast (column) dimension
        const int tile_i = 32;   // tile in slow (row) dimension

        // Common Vars/RVars used in schedules.
        Var jo("jo"), ji("ji"), io("io"), ii("ii"), tile("tile");
        RVar rxo("rxo"), rxi("rxi"), ryo("ryo"), ryi("ryi");

        // ---------------- ey1 scheduling ----------------
        // Pure stage: copy from ey_param.
        //
        // We tile (j,i), fuse tile indices into a single parallel
        // dimension, and vectorize across the contiguous j-dimension.
        ey1
            .compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            .fuse(jo, io, tile)
            .parallel(tile)
            .vectorize(ji, vec_width);

        // ey1 update 0: boundary row ey[0][j] = fict[t]
        {
            RVar r0_outer("r0_outer"), r0_inner("r0_inner");
            ey1.update(0)
                .split(r_ey0.x, r0_outer, r0_inner, tile_j)
                .parallel(r0_outer)
                .vectorize(r0_inner, vec_width);
        }

        // ey1 update 1: interior ey
        {
            RVar x_outer("x_outer"), x_inner("x_inner");
            RVar y_outer("y_outer"), y_inner("y_inner");
            RVar tile_ey("tile_ey");

            ey1.update(1)
                // r_ey1.y is i (rows), r_ey1.x is j (cols)
                .split(r_ey1.y, y_outer, y_inner, tile_i)
                .split(r_ey1.x, x_outer, x_inner, tile_j)
                .reorder(x_inner, y_inner, x_outer, y_outer)
                .fuse(y_outer, x_outer, tile_ey)
                .parallel(tile_ey)
                .vectorize(x_inner, vec_width);
        }

        // ---------------- ex1 scheduling ----------------
        // Pure stage: copy from ex_param.
        ex1
            .compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            .fuse(jo, io, tile)
            .parallel(tile)
            .vectorize(ji, vec_width);

        // ex1 update 0: interior ex
        {
            RVar x_outer_ex("x_outer_ex"), x_inner_ex("x_inner_ex");
            RVar y_outer_ex("y_outer_ex"), y_inner_ex("y_inner_ex");
            RVar tile_ex("tile_ex");

            ex1.update(0)
                // r_ex.y is i (rows), r_ex.x is j (cols)
                .split(r_ex.y, y_outer_ex, y_inner_ex, tile_i)
                .split(r_ex.x, x_outer_ex, x_inner_ex, tile_j)
                .reorder(x_inner_ex, y_inner_ex, x_outer_ex, y_outer_ex)
                .fuse(y_outer_ex, x_outer_ex, tile_ex)
                .parallel(tile_ex)
                .vectorize(x_inner_ex, vec_width);
        }

        // ---------------- hz1 scheduling ----------------
        // Pure stage: copy from hz_param.
        hz1
            .compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            .fuse(jo, io, tile)
            .parallel(tile)
            .vectorize(ji, vec_width);

        // hz1 update 0: interior hz uses updated ex1 and ey1
        {
            RVar x_outer_hz("x_outer_hz"), x_inner_hz("x_inner_hz");
            RVar y_outer_hz("y_outer_hz"), y_inner_hz("y_inner_hz");
            RVar tile_hz("tile_hz");

            hz1.update(0)
                // r_hz.y is i (rows), r_hz.x is j (cols)
                .split(r_hz.y, y_outer_hz, y_inner_hz, tile_i)
                .split(r_hz.x, x_outer_hz, x_inner_hz, tile_j)
                .reorder(x_inner_hz, y_inner_hz, x_outer_hz, y_outer_hz)
                .fuse(y_outer_hz, x_outer_hz, tile_hz)
                .parallel(tile_hz)
                .vectorize(x_inner_hz, vec_width);
        }
    }

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    Target jit_target = get_jit_target_from_environment();
    fdtd_step.compile_jit(jit_target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven, strictly sequential in t).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration (ring buffer in time).
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ex_final(j, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ey_final(j, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << hz_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
