    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // -----------------------
    // Initialization schedule
    // -----------------------
    //
    // We do this once, but it can still be parallelized/vectorized cheaply.
    Target init_target = get_host_target();
    int init_vec = init_target.natural_vector_size(type_of<num_t>());
    if (init_vec <= 0) {
        init_vec = 1;
    }

    // Parallelize the 1D fict array.
    init_fict.compute_root()
             .parallel(t);

    // For the 2D fields, i is the slow (row) dim, j is the fast (contiguous) dim.
    // Parallelize across rows and vectorize across columns.
    init_ex.compute_root()
           .parallel(i)
           .vectorize(j, init_vec);

    init_ey.compute_root()
           .parallel(i)
           .vectorize(j, init_vec);

    init_hz.compute_root()
           .parallel(i)
           .vectorize(j, init_vec);

