               "r_ey1");

    ey1(r_ey1.x, r_ey1.y) =
        ey1(r_ey1.x, r_ey1.y) -
        half * (hz_param(r_ey1.x, r_ey1.y) - hz_param(r_ey1.x, r_ey1.y - 1));

    // ------------------------------------------------------------
    // C code:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide: i in [0..nx-1], j in [1..ny-1]
    // ------------------------------------------------------------
    RDom r_ex(1, ex_param.dim(0).extent() - 1,   // j: 1 .. ny-1
              0, ex_param.dim(1).extent(),       // i: 0 .. nx-1
              "r_ex");

    ex1(r_ex.x, r_ex.y) =
        ex1(r_ex.x, r_ex.y) -
        half * (hz_param(r_ex.x, r_ex.y) - hz_param(r_ex.x - 1, r_ex.y));

    // ------------------------------------------------------------
    // C code:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Halide: i in [0..nx-2], j in [0..ny-2]
    // ------------------------------------------------------------
    RDom r_hz(0, hz_param.dim(0).extent() - 1,   // j: 0 .. ny-2
              0, hz_param.dim(1).extent() - 1,   // i: 0 .. nx-2
              "r_hz");

    hz1(r_hz.x, r_hz.y) =
        hz1(r_hz.x, r_hz.y) -
        seven_tenths *
        ((ex1(r_hz.x + 1, r_hz.y) - ex1(r_hz.x, r_hz.y)) +
         (ey1(r_hz.x, r_hz.y + 1) - ey1(r_hz.x, r_hz.y)));

    // ------------------------------------------------------------
    // Scheduling for a single time-step
    // ------------------------------------------------------------
    //
    // Goal:
    //  - i (row) is the slow dimension, j (column) is the fast dimension.
    //  - Parallelize over rows to exploit 32 cores.
    //  - Vectorize over columns to use SIMD.
    //  - Keep the time loop on the host (sequential), as required by
    //    the FDTD temporal dependence.
    //
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // Convenience aliases for the RVars we want to schedule.
    RVar r_ey0_x = r_ey0.x;

    RVar r_ey1_x = r_ey1.x;
    RVar r_ey1_y = r_ey1.y;

    RVar r_ex_x = r_ex.x;
    RVar r_ex_y = r_ex.y;

    RVar r_hz_x = r_hz.x;
    RVar r_hz_y = r_hz.y;

    // -------- ey1 schedule --------
    //
    // Pure definition: copy ey from previous time step.
    // Parallelize across rows (i) and vectorize across columns (j).
    ey1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    // Update 0: boundary row i == 0.
    // Just a 1D sweep over j; vectorize it.
    ey1.update(0)
       .vectorize(r_ey0_x, vec_width);

    // Update 1: interior ey update over i >= 1.
    // Parallelize across rows (r_ey1_y ~ i) and vectorize across columns (r_ey1_x ~ j).
    ey1.update(1)
       .parallel(r_ey1_y)
       .vectorize(r_ey1_x, vec_width);

    // -------- ex1 schedule --------
    //
    // Pure definition: copy ex from previous time step.
    ex1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    // Single update: interior ex update over j >= 1.
    ex1.update(0)
       .parallel(r_ex_y)          // r_ex.y ~ i
       .vectorize(r_ex_x, vec_width); // r_ex.x ~ j

    // -------- hz1 schedule --------
    //
    // Pure definition: copy hz from previous time step.
    hz1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    // Single update: interior hz update (i < nx-1, j < ny-1).
    hz1.update(0)
       .parallel(r_hz_y)          // r_hz.y ~ i
       .vectorize(r_hz_x, vec_width); // r_hz.x ~ j

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven, strictly sequential in t).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << ex_final(jj, ii) << '\n';
            }
        }

        // Print ey
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << ey_final(jj, ii) << '\n';
            }
        }

        // Print hz
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << hz_final(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
